<?php
require_once dirname(__DIR__,3).'/app/AdminBusinessOperations.php';
$operationApplications=AdminBusinessOperations::applications(db());
$operationRows=AdminBusinessOperations::summarize($rows,$operationApplications);
$filters=['query'=>trim((string)($_GET['q']??'')),'destination'=>(string)($_GET['destino']??''),'category'=>(string)($_GET['categoria']??''),'status'=>(string)($_GET['estado']??''),'origin'=>(string)($_GET['origen']??''),'verification'=>(string)($_GET['verificacion']??''),'plan'=>(string)($_GET['plan']??''),'account'=>(string)($_GET['cuenta']??'')];
if($filters['destination']==='0')$filters['destination']='';
$viewRows=array_values(array_filter($operationRows,static fn($row)=>($tab!=='atencion'||$row['in_attention'])&&($tab!=='pendientes'||$row['in_review'])&&AdminBusinessOperations::matches($row,$filters)));
$unlinked=array_values(array_filter($operationApplications,static function($item)use($filters,$tab){
    if($tab==='lista'||$item['business_id']||!in_array($item['status'],['pending','in_review'],true))return false;
    if($filters['status']!==''||$filters['origin']!==''||$filters['verification']!==''||$filters['account']!==''||$filters['plan']!=='')return false;
    if($filters['destination']!==''&&(int)$item['destination_id']!==(int)$filters['destination'])return false;
    if($filters['category']!==''&&$item['category_code']!==$filters['category'])return false;
    if($filters['query']!==''&&mb_stripos($item['business_name'].' '.$item['destination_name'],$filters['query'])===false)return false;
    $details=json_decode($item['business_details_json']??'{}',true)?:[];
    return $filters['plan']===''||($details['requested_subscription']['plan_code']??'none')===$filters['plan'];
}));
$operationEntries=array_merge(array_map(static fn($row)=>['kind'=>'business','row'=>$row],$viewRows),array_map(static fn($row)=>['kind'=>'application','row'=>$row],$unlinked));
$operationPageCount=max(1,(int)ceil(count($operationEntries)/25));$operationPage=min(max(1,(int)($_GET['pagina']??1)),$operationPageCount);
$operationShown=array_slice($operationEntries,($operationPage-1)*25,25);
$filterFields=['destino'=>['Destino',array_column($options['destinations'],'display_name','id'),'destination'],'categoria'=>['Categoría',array_column($options['categories'],'label','code'),'category'],'estado'=>['Publicación',['draft'=>'Pendiente de publicación','published'=>'Publicado','archived'=>'Retirado'],'status'],'origen'=>['Origen',['public_import'=>'Importación pública','owner_submitted'=>'Solicitud del negocio','admin_created'=>'Alta administrativa'],'origin'],'plan'=>['Suscripción',[],'plan'],'cuenta'=>['Cuenta asociada',['yes'=>'Con cuenta asociada','no'=>'Sin cuenta asociada'],'account']];
// Plan options are read from current configuration, not inferred from payment or origin.
$filterFields['plan'][1]=['free'=>'Gratis'];foreach($options['plans'] as $planOption){$code=$planOption['code']??$planOption['plan_code']??null;if($code)$filterFields['plan'][1][$code]=$planOption['name']??$planOption['label']??$code;}
$operationUrl=static fn($page)=>'?'.http_build_query(array_merge(array_intersect_key($_GET,array_flip(['q','destino','categoria','estado','origen','verificacion','plan','cuenta'])),['tab'=>$tab,'pagina'=>$page]));
?>
<section class="destination-admin-list">
<h2><?=esc(['lista'=>'Catálogo y cobertura','atencion'=>'Solicitudes y seguimiento','pendientes'=>'Pendientes de revisión'][$tab])?></h2>
<p><?=esc($tab==='lista'?'Todas las fichas del catálogo. Origen, cuenta, plan y publicación se muestran por separado.':($tab==='atencion'?'Fichas con solicitudes de cuenta documentadas y solicitudes pendientes que todavía no tienen ficha. Una cuenta asociada se puede filtrar aparte; no prueba titularidad.':'Borradores de cualquier origen y solicitudes pendientes. Esta vista informa pendientes; no aprueba, asocia ni publica negocios.'))?></p>
<form method="get" class="business-filter-bar"><input type="hidden" name="tab" value="<?=esc($tab)?>"><label>Buscar negocio o destino<input type="search" name="q" value="<?=esc($filters['query'])?>"></label>
<?php foreach($filterFields as $name=>[$label,$values,$key]):?><label><?=esc($label)?><select name="<?=esc($name)?>" data-native-select><option value="">Todos</option><?php foreach($values as $value=>$text):?><option value="<?=esc($value)?>" <?=(string)$value===$filters[$key]?'selected':''?>><?=esc($text)?></option><?php endforeach ?></select></label><?php endforeach ?>
<label>Verificación<select name="verificacion" data-native-select><option value="">Todas</option><?php foreach(['PUBLICO'=>'Fuente pública','VERIFICADO'=>'Verificado','ACTIVO'=>'Activo','PENDIENTE_REVISION'=>'Pendiente de revisión'] as $value=>$text):?><option value="<?=$value?>" <?=$filters['verification']===$value?'selected':''?>><?=$text?></option><?php endforeach ?></select></label>
<button class="pill compact" type="submit">Aplicar filtros</button><a class="pill light compact" href="?tab=<?=esc($tab)?>">Limpiar filtros</a></form>
<p class="notice" role="status"><?=count($viewRows)?> negocios distintos · <?=count($unlinked)?> solicitudes pendientes sin ficha · Página <?=$operationPage?> de <?=$operationPageCount?>. <?=count(array_filter($filters,static fn($value)=>$value!==''))?> filtros activos. Las solicitudes sin ficha solo se incluyen sin filtros de publicación, origen, verificación, plan registrado o cuenta asociada.</p>
<div class="destination-admin-table admin-operations-table"><table><thead><tr><th>Negocio / solicitud</th><th>Destino y categorías</th><th>Publicación</th><th>Cuenta y solicitud</th><th>Plan</th><th>Pendiente y acciones</th></tr></thead><tbody>
<?php foreach($operationShown as $entry):$row=$entry['row'];if($entry['kind']==='application'):?>
<tr><td><strong><?=esc($row['business_name'])?></strong><br>Solicitud sin ficha #<?=esc($row['id'])?></td><td><?=esc($row['destination_name'])?><br><?=esc($filterFields['categoria'][1][$row['category_code']]??$row['category_code'])?></td><td>No existe ficha todavía</td><td><?=esc($row['status']==='pending'?'Pendiente':'En revisión')?></td><td>Consultar elección enviada; aún no es una suscripción</td><td><a class="pill light compact" href="solicitud-detalle.php?tipo=account&amp;id=<?=esc($row['id'])?>" target="_blank" rel="noopener">Revisar solicitud ↗</a></td></tr>
<?php else:?>
<tr><td><strong><?=esc($row['display_name'])?></strong><br><small>Origen registrado: <?=esc(business_origin_label($row['record_origin']))?> · #<?=esc($row['id'])?></small></td><td><?=esc($row['destination_name'])?><br><?=esc(implode(' · ',$row['category_labels']))?></td><td><?=esc(['draft'=>'Pendiente de publicación','published'=>'Publicado','archived'=>'Retirado'][$row['publication_status']]??$row['publication_status'])?><br><small><?=esc(AdminBusinessOperations::informationLabel($row['information_status']))?></small></td><td><?=esc(AdminBusinessOperations::accountLabel($row))?><br><small><?=count($row['applications'])?> solicitudes vinculadas</small><?php foreach($row['applications'] as $application):?><br><a href="solicitud-detalle.php?tipo=account&amp;id=<?=esc($application['id'])?>" target="_blank" rel="noopener">Solicitud #<?=esc($application['id'])?> ↗</a><?php endforeach ?></td><td><?=esc($row['subscription_status']==='sin suscripción'?'Gratis':($filterFields['plan'][1][$row['plan_code']]??$row['plan_code']))?><br><small><?=esc(AdminBusinessOperations::subscriptionLabel($row['subscription_status']))?></small></td><td><?=esc(AdminBusinessOperations::nextStep($row))?><div class="admin-row-actions"><a class="pill light compact" href="negocio-vista-previa.php?id=<?=esc($row['id'])?>" target="_blank" rel="noopener">Ver tarjeta ↗</a><a class="pill light compact" href="negocios.php?id=<?=esc($row['id'])?>" target="_blank" rel="noopener">Editar datos ↗</a><a class="pill light compact" href="suscripciones.php?id=<?=esc($row['id'])?>" target="_blank" rel="noopener">Gestionar plan y publicación ↗</a></div></td></tr>
<?php endif;endforeach ?><?php if(!$operationShown):?><tr><td colspan="6">No hay registros con estos filtros. Puedes limpiar filtros o consultar el catálogo completo.</td></tr><?php endif ?></tbody></table></div>
<nav class="admin-pagination" aria-label="Páginas de negocios"><?php if($operationPage>1):?><a href="<?=esc($operationUrl($operationPage-1))?>">← Anterior</a><?php endif ?><?php if($operationPage<$operationPageCount):?><a href="<?=esc($operationUrl($operationPage+1))?>">Siguiente →</a><?php endif ?></nav></section>
